<?php require 'includes/config.php';$pageTitle='Register';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$st=$pdo->prepare("INSERT INTO users(name,email,password) VALUES(?,?,?)");$st->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT)]);header('Location: login.php?created=1');exit;}catch(Exception $e){$error='This email is already registered.';}}include 'includes/header.php';?>
